from s114_course_common import teach
S='keratometry-p1'
teach(S,'corneal-optics-1',[
(0,'角膜是前窗，水晶體是裡面可調的鏡片','K值描述角膜收光估值，不是整眼處方。',[('角膜cornea','眼前透明曲面，提供主要屈光力'),('水晶體lens','眼內可調節的透明構造'),('網膜retina','眼底接光層，焦要落在這裡')],'整眼約60D、角膜約占三分之二是近似說法；有間距的各光學面不能一律當接觸薄鏡直接相加。'),
(2,'小球表面彎得急，大球表面較平','半徑小，不是角膜尺寸小，而是局部彎曲較陡。',[('r','曲率半徑，單位mm'),('K','由半徑估出的角膜力量，單位D'),('K＝337.5/r','r越小，K越大；1.3375是換算假設指數')],'例如r7.5mm →K45D；不能把45D當近視4500度。'),
(4,'角膜強，不代表整眼一定近視','眼軸、水晶體和角膜一起決定最後屈光。',[('K較高','說明測到角膜較陡'),('處方R','眼放鬆時需要多少矯正'),('驗光儀與角膜儀','前者估全眼屈光；後者重點是角膜曲率')],'屈光前表面中央區、重要視覺區與儀器實際取樣區不必完全同一大小。')])
teach(S,'keratometer-method-1',[
(0,'看角膜反射出的標像，推它彎不彎','像在彎鏡面上看同一組圖案如何變形。',[('Mire','儀器投出的測標在角膜上的反射像'),('Keratometer','角膜曲率儀，取前表面中央小區域估曲率'),('量測條件','淚膜、對焦和定位都會影響標像')],'傳統K常約取中央3mm，機型可不同；不是整個角膜的掃描。'),
(2,'兩個K讀數，是兩個方向各自的力量','@後面寫方向，前面寫D。',[('42.50@180','水平方向估計42.50D'),('43.50@90','垂直方向43.50D，較陡'),('MCAR','mires clear and regular，反射標像清楚規則')],'差值1D是角膜散光估量；負柱鏡軸沿較平的180方向。'),
(4,'標像扭曲：先查測量條件，再想角膜形狀','一次扭曲不能直接確診圓錐角膜。',[('淚膜不穩','反射面會暫時不平整，眨眼後可變化'),('定位／對焦偏差','也會讓讀值不穩'),('持續異常','需結合重測、地圖與其他眼部檢查')],'記錄清楚規則或扭曲，是告訴後續讀者這組K值有多可靠。')])
teach(S,'astigmatism-javal-1',[
(0,'先找角膜最強方向，再想矯正軸','K的方向，不等於負柱鏡的軸。',[('垂直K較強','順規；負軸近水平'),('水平K較強','逆規；負軸近垂直'),('斜方向較強','需按題目角度範圍判斜散光')],'一個是在說眼睛收光；另一個在說鏡片哪裡不額外加C，對象不同。'),
(2,'K差是大小，還要留下方向','45@90、43@180 →差2D，負軸180。',[('兩K相減','取較大減較小，得角膜散光量'),('負柱鏡軸','沿較平的主方向'),('總眼散光','還有角膜後面與水晶體等貢獻')],'不同軸的角膜與眼內散光合成要用方向分析，不能一律做大小加減。'),
(4,'Javal是在預測，不是在直接量全眼','逆規0.50D是一個帶方向的散光項。',[('簡易規則','順規角膜量常預估減0.50D'),('Javal','角膜散光乘1.25，再合成0.50D逆規'),('順規與逆規','逆規項可抵消順規，也可加重逆規')],'題目指定哪套才用哪套；實際全眼處方仍需驗光，不能用預測取代。')])
teach(S,'topography-1',[
(0,'角膜地圖：用顏色標每一區的數值','先看圖例，紅藍本身不是疾病名稱。',[('Topography','表面形狀的地形圖'),('相同色階下','暖色常較陡、冷色常較平'),('色階／地圖類型','換刻度或地圖，顏色不能直接逐張比')],'看顏色同時讀D或半徑與圖例；不能只說「紅＝不好」。'),
(2,'一組K，和一張地圖，涵蓋範圍不同','Placido反射圖主要重建角膜前表面。',[('傳統K','中央有限區域，兩主方向估值'),('地形圖','較廣範圍看形狀與對稱'),('斷層測量tomography','其他設備可提供後表面或厚度，別混作同一技術')],'地圖的Sim K是模擬傳統K的摘要，仍不是整眼屈光處方。'),
(4,'不規則散光：不同區域不能用同一套S/C概括','先查圖品質，才判形狀是否持續不規則。',[('圓錐角膜','角膜變薄、局部向前突出，可產生不規則散光'),('框架眼鏡','對規則部分有幫助，不一定能完全補償'),('硬式／鞏膜鏡','可提供較規則光學面；改善視力不等於阻止進展')],'不能只靠一塊紅色或一次高K唯一確診。')])
